mapper.select:
SELECT id, login_id, nickname, password_hash, provider, provider_id, role, created_at, updated_at
FROM users
WHERE id = #{id}

SELECT id, login_id, nickname, password_hash, provider, provider_id, role, created_at, updated_at
FROM users
WHERE login_id = #{loginId}

SELECT id, login_id, nickname, password_hash, provider, provider_id, role, created_at, updated_at
FROM users
WHERE provider = #{provider}
  AND provider_id = #{providerId}

SELECT id, login_id, nickname, password_hash, provider, provider_id, role, created_at, updated_at
FROM users
WHERE nickname = #{nickname}

mapper.update:
UPDATE users
SET role = #{role}
WHERE id = #{id}
